package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.security.*;import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;
class SignedObservationControlPlaneTest {
 static class Time extends Clock{Instant now=Instant.parse("2026-11-13T00:00:00Z");public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now;}}
 static KeyPair key(){try{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}catch(Exception e){throw new RuntimeException(e);}}
 static byte[] signature(KeyPair key,byte[] body){try{var s=Signature.getInstance("Ed25519");s.initSign(key.getPrivate());s.update(body);return s.sign();}catch(Exception e){throw new RuntimeException(e);}}
 static SignedObservationControlPlane.Context context(){return new SignedObservationControlPlane.Context("run-1","a".repeat(64),"tea-fixed","srv-fixed","dep-new","reviewed",Set.of("dep-old"));}
 static Map<String,Object> payload(SignedObservationControlPlane relay,Clock clock){var c=relay.challenge();var p=new TreeMap<String,Object>();p.put("version",1);p.put("provenance",c.provenance());p.put("run",c.run());p.put("challenge",c.challenge());p.put("target",c.target());p.put("workspace",c.workspace());p.put("service",c.service());p.put("deployment",c.deployment());p.put("revision",c.revision());p.put("capturedAt",clock.instant().toString());p.put("services",1);p.put("instances",1);p.put("autoDeploy",false);p.put("previews",false);p.put("deployments",List.of(Map.of("id","dep-new","revision","reviewed","state","live"),Map.of("id","dep-old","revision","old","state","deactivated")));return p;}
 static byte[] bytes(Map<String,Object> payload){return NativeCommitJournal.canonical(payload).getBytes(StandardCharsets.UTF_8);}
 @Test void exactSignedCycleIsOneUse(){var k=key();var t=new Time();try(var r=new SignedObservationControlPlane(k.getPublic(),context(),t)){byte[] p=bytes(payload(r,t));r.submit(p,signature(k,p));assertEquals("dep-new",r.await().deployment());assertThrows(RuntimeException.class,()->r.submit(p,signature(k,p)));}}
 @Test void unsignedNoiseDoesNotPoisonLegitimateCycle(){var k=key();var t=new Time();try(var r=new SignedObservationControlPlane(k.getPublic(),context(),t)){byte[] p=bytes(payload(r,t));assertThrows(RuntimeException.class,()->r.submit(p,signature(key(),p)));r.submit(p,signature(k,p));assertEquals(1,r.await().instances());}}
 @Test void validSignatureWrongContextClosesCycle(){var k=key();var t=new Time();try(var r=new SignedObservationControlPlane(k.getPublic(),context(),t)){var p=payload(r,t);p.put("target","b".repeat(64));byte[] b=bytes(p);assertThrows(RuntimeException.class,()->r.submit(b,signature(k,b)));assertThrows(RuntimeException.class,r::challenge);}}
 @Test void staleOrIncompleteInventoryNeverProvesOwnership(){for(String reason:List.of("stale","activeOld","extraField","noncanonical")){var k=key();var t=new Time();try(var r=new SignedObservationControlPlane(k.getPublic(),context(),t)){var p=payload(r,t);switch(reason){case "stale"->p.put("capturedAt",t.instant().minusSeconds(60).toString());case "activeOld"->p.put("deployments",List.of(Map.of("id","dep-new","revision","reviewed","state","live"),Map.of("id","dep-old","revision","old","state","live")));case "extraField"->p.put("capability",true);}byte[] b=bytes(p);if(reason.equals("noncanonical"))b=(new String(b,StandardCharsets.UTF_8)+" ").getBytes(StandardCharsets.UTF_8);final byte[] wire=b;assertThrows(RuntimeException.class,()->r.submit(wire,signature(k,wire)),reason);}}}
 @Test void expiryAndCancellationInvalidateAcceptedObservation(){for(boolean cancel:List.of(false,true)){var k=key();var t=new Time();try(var r=new SignedObservationControlPlane(k.getPublic(),context(),t)){byte[] p=bytes(payload(r,t));r.submit(p,signature(k,p));if(cancel)r.close();else t.now=t.now.plusSeconds(60);assertThrows(RuntimeException.class,r::await);}}}
}
